window.DEX_DATA["sources:backport-7e9ea2a3aa0c1334"]={"json":{"skins":[{"filename":"psychic_f.png"}],"names":[{"name":"玛丽亚"},{"name":"沃耶兹夫人"},{"name":"卢泰西亚"},{"name":"阿里阿德涅"},{"name":"娜塔莎"}],"chat":[{"lines":[{"text":"想看我展示本事？先把金币交出来吧。"},{"text":"我已经看见你要遇上麻烦了！"}]},{"lines":[{"text":"我能读懂你的想法：宝可梦，除了宝可梦还是宝可梦。"},{"text":"真没意思，走开吧！"}]},{"lines":[{"text":"我能预测未来！你会经历许多战斗，还有一点点荣耀。"},{"text":"再给几枚金币，我肯定能看见更多荣耀。"}]},{"lines":[{"text":"你找到了世界上最厉害的占卜师！尽管问吧！"},{"text":"下场战斗该用哪只宝可梦？我怎么知道？去去去！"}]}]}};
